/// `line_count` lines) that contain every query at least once across the
/// window. When a larger window strictly contains a smaller valid window, only
/// the smaller (tightest) window is retained.
fn minimal_covering_windows(
    per_line: &[Vec<usize>],
    num_queries: usize,
    line_count: usize,
) -> Vec<(usize, usize)> {
    let n = per_line.len();
    let mut counts = vec![0usize; num_queries];
    let mut satisfied = 0usize;
    let mut right = 0usize;
    let mut windows: Vec<(usize, usize)> = Vec::new();

    for left in 0..n {
        // Expand the right edge until every query is present in [left, right).
        while right < n && satisfied < num_queries {
            for &query in &per_line[right] {
                if counts[query] == 0 {
                    satisfied += 1;
                }
                counts[query] += 1;
            }
            right += 1;
        }

